  res.status(200).json({
    mem: process.memoryUsage(),
    uptime: process.uptime(),
    latency: getLatencyPercentiles(),
    sync: getSyncStats(),
    sessions: { active: sessionCount, expiringWithin14Days: expiringCount },
  });
});
