 66→  console.log('Logging in via ' + loginMethod);
 67→  let tokenRes: { error?: string; token?: string } | null = null;
 68→  switch (loginMethod) {
 69→    case 'header': {
 70→      const headerVal = req.get('x-actual-password') || '';
 71→      const obfuscated =
 72→        '*'.repeat(headerVal.length) || 'No password provided.';
 73→      console.debug('HEADER VALUE: ' + obfuscated);
 74→      if (headerVal === '') {
