 81→          res.send({ status: 'error', reason: 'proxy-not-trusted' });
 82→          return;
 83→        }
 84→      }
 85→      break;
 86→    }
 87→    case 'openid': {
 88→      if (!isValidRedirectUrl(req.body.returnUrl)) {
 89→        res
 90→          .status(400)
 91→          .send({ status: 'error', reason: 'Invalid redirect URL' });
