 51→// OAuth callback from the bank's redirect. The bank appends ?code=...&state=...
 52→// to the redirect URL. We validate the state against eb_sessions (CSRF guard),
 53→// exchange the code for a real session, persist accounts, then redirect to /link.
 54→app.get(
 55→  '/callback',
 56→  handleError(async (req, res) => {
 57→    const { code, state } = req.query;
 58→
 59→    if (!state) {
 60→      return res.status(400).send('Missing state parameter');
 61→    }
 62→
 63→    const db = getAccountDb();
 64→
 65→    // CSRF guard: state must exist in eb_sessions (inserted at create-auth time).
 66→    const sessionRow = db.first('SELECT * FROM eb_sessions WHERE state = ?', [
 67→      state,
 68→    ]);
 69→
 70→    if (!sessionRow) {
 71→      return res.status(400).send('Invalid or expired state parameter');
 72→    }
 73→
 74→    // Exchange the authorization code for a real Enable Banking session.
 75→    const { session_id, accounts, valid_until } = await exchangeCode(code);
 76→
 77→    // Update the session row with the real session ID and account list.
 78→    db.mutate(
 79→      'UPDATE eb_sessions SET id = ?, accounts = ?, valid_until = ? WHERE state = ?',
 80→      [session_id, JSON.stringify(accounts), valid_until ?? null, state],
 81→    );
 82→
 83→    // Pre-populate eb_account_map for each account returned by the session.
 84→    // actual_account_id is left NULL here - it is filled in at link time by
 85→    // the enablebanking-accounts-link IPC handler via POST /update-account-map.
 86→    //
 87→    // CRITICAL: Uses account.uid (UUID string from Enable Banking), NOT
 88→    // account.account_id (which is an object like { iban: "..." }).
 89→    // This MUST match normalizeAccount() in utils.js so the UID stored here
 90→    // equals the account_id field that SelectLinkedAccountsModal receives.
 91→    for (const account of accounts) {
 92→      const ebAccountUid = account.uid;
 93→      db.mutate(
 94→        'INSERT OR IGNORE INTO eb_account_map (eb_account_uid, session_id) VALUES (?, ?)',
 95→        [ebAccountUid, session_id],
 96→      );
 97→    }
 98→
 99→    // Redirect to the link page which auto-closes the popup.
100→    res.redirect('/enablebanking/link?state=' + encodeURIComponent(state));
101→  }),
