314→// Removes all data associated with an Enable Banking session (account map rows
315→// and the session itself). Called when the user unlinks a bank.
316→app.post(
317→  '/remove-session',
318→  handleError(async (req, res) => {
319→    const { sessionId } = req.body || {};
320→    const db = getAccountDb();
321→    db.mutate('DELETE FROM eb_account_map WHERE session_id = ?', [sessionId]);
322→    db.mutate('DELETE FROM eb_sessions WHERE id = ?', [sessionId]);
323→    res.send({ status: 'ok' });
324→  }),
