327→// Returns the last sync log entry per requested account (by Actual UUID),
328→// extended with consent expiry and session identity from eb_sessions so
329→// the client can display banner warnings and the per-account consent column.
330→//
331→// Never-synced accounts (null lastEntry) receive explicit defaults so the
332→// client always sees all expected fields rather than undefined.
333→//
334→// Note: synced_at is stored as a Unix epoch INTEGER in eb_sync_log.
335→// It is converted to an ISO string here so the client receives a consistent
336→// format regardless of how the value was written.
337→app.post(
338→  '/sync-status',
339→  handleError(async (req, res) => {
340→    const { accountIds } = req.body || {};
341→    const db = getAccountDb();
342→    const statuses = {};
343→
344→    for (const accountId of accountIds || []) {
345→      const lastEntry = db.first(
346→        'SELECT * FROM eb_sync_log WHERE actual_account_id = ? ORDER BY id DESC LIMIT 1',
347→        [accountId],
348→      );
349→
350→      const mapRow = db.first(
351→        'SELECT session_id FROM eb_account_map WHERE actual_account_id = ?',
352→        [accountId],
353→      );
354→      const session = mapRow
355→        ? db.first(
356→            'SELECT valid_until, aspsp_name, aspsp_country FROM eb_sessions WHERE id = ?',
357→            [mapRow.session_id],
358→          )
359→        : null;
360→
361→      // Null-guard: when lastEntry is null (account linked but never synced),
362→      // provide explicit defaults so the client always sees all expected fields.
363→      const defaultEntry = {
364→        synced_at: null,
365→        status: null,
366→        error_message: null,
367→        transactions_added: 0,
368→        transactions_updated: 0,
369→        error_code: null,
370→      };
371→
372→      statuses[accountId] = {
373→        ...(lastEntry ?? defaultEntry),
374→        // Convert synced_at from Unix epoch integer to ISO string for the client.
375→        synced_at: lastEntry?.synced_at
376→          ? new Date(Number(lastEntry.synced_at) * 1000).toISOString()
377→          : null,
378→        consent_valid_until: session?.valid_until ?? null,
379→        session_id: mapRow?.session_id ?? null,
380→        aspsp_name: session?.aspsp_name ?? null,
381→        aspsp_country: session?.aspsp_country ?? null,
382→      };
383→    }
384→
385→    res.send({ status: 'ok', data: { statuses } });
386→  }),
387→);
388→
389→// Updates eb_account_map to point all accounts from an old session to the new
390→// one after a re-authorization flow. Called by the client modal once the OAuth
391→// callback has completed and a new session_id is available.
392→app.post(
393→  '/reauth-complete',
394→  handleError(async (req, res) => {
395→    const { newSessionId, oldSessionId } = req.body || {};
396→    if (!newSessionId || !oldSessionId) {
397→      return res.send({ status: 'ok', data: { error_code: 'INVALID_INPUT' } });
398→    }
399→    const db = getAccountDb();
400→
401→    // Update all account map rows from old session to new session
402→    db.mutate('UPDATE eb_account_map SET session_id = ? WHERE session_id = ?', [
403→      newSessionId,
404→      oldSessionId,
405→    ]);
406→
407→    console.log(
408→      `[eb] Re-auth complete: session ${oldSessionId} -> ${newSessionId}`,
409→    );
410→
411→    res.send({ status: 'ok', data: {} });
412→  }),
413→);
414→
415→// Populates actual_account_id in eb_account_map at account link time.
416→// Called by the enablebanking-accounts-link IPC handler (loot-core app.ts)
417→// immediately after the Actual account is created or upgraded.
418→// This is what makes /sync-status work: without actual_account_id in the map,
419→// /transactions cannot log by Actual UUID and status queries return no results.
420→app.post(
421→  '/update-account-map',
422→  handleError(async (req, res) => {
423→    const { ebAccountUid, actualAccountId } = req.body || {};
424→
425→    if (!ebAccountUid || !actualAccountId) {
426→      return res.send({
427→        status: 'ok',
428→        data: {
429→          error_code: 'INVALID_INPUT',
430→          error_type: 'validation-error',
431→        },
432→      });
433→    }
434→
435→    const db = getAccountDb();
436→
437→    // Verify the EB account UID exists in the map before updating.
438→    const existing = db.first(
439→      'SELECT eb_account_uid FROM eb_account_map WHERE eb_account_uid = ?',
440→      [ebAccountUid],
441→    );
442→
443→    if (!existing) {
444→      return res.send({
445→        status: 'ok',
446→        data: {
447→          error_code: 'ACCOUNT_NOT_FOUND',
448→          error_type: 'validation-error',
449→        },
450→      });
451→    }
452→
453→    db.mutate(
454→      'UPDATE eb_account_map SET actual_account_id = ? WHERE eb_account_uid = ?',
455→      [actualAccountId, ebAccountUid],
456→    );
457→    res.send({ status: 'ok' });
458→  }),
459→);
