180→function parseHTTPSConfig(value: string) {
181→  if (value.startsWith('-----BEGIN')) {
182→    return value;
183→  }
184→  return fs.readFileSync(value);
185→}
186→
187→function sendServerStartedMessage() {
188→  // Signify to any parent process that the server has started. Used in electron desktop app
189→  // oxlint-disable-next-line typescript/ban-ts-comment
190→  // @ts-ignore-error electron types
191→  process.parentPort?.postMessage({ type: 'server-started' });
192→  console.log(
193→    'Listening on ' + config.get('hostname') + ':' + config.get('port') + '...',
194→  );
195→}
196→
197→export async function run() {
198→  const portVal = config.get('port');
199→  const port = typeof portVal === 'string' ? parseInt(portVal) : portVal;
200→  const hostname = config.get('hostname');
201→  const openIdConfig = config?.getProperties()?.openId;
202→  if (
203→    openIdConfig?.discoveryURL ||
204→    openIdConfig?.issuer?.authorization_endpoint
205→  ) {
206→    console.log('OpenID configuration found. Preparing server to use it');
207→    try {
208→      const { error } = await bootstrap({ openId: openIdConfig }, true);
209→      if (error) {
210→        console.log(error);
211→      } else {
212→        console.log('OpenID configured!');
213→      }
214→    } catch (err) {
215→      console.error(err);
216→    }
217→  }
218→
219→  if (config.get('https.key') && config.get('https.cert')) {
220→    const https = await import('node:https');
221→    const httpsOptions = {
222→      ...config.get('https'),
223→      key: parseHTTPSConfig(config.get('https.key')),
224→      cert: parseHTTPSConfig(config.get('https.cert')),
225→    };
226→    https.createServer(httpsOptions, app).listen(port, hostname, () => {
227→      sendServerStartedMessage();
228→    });
229→  } else {
230→    app.listen(port, hostname, () => {
231→      sendServerStartedMessage();
232→    });
233→  }
234→
235→  // [eb] Start the 6-hour auto-sync scheduler. No-op when ENABLE_AUTO_SYNC != 'true'.
236→  // EB database tables are ready because runMigrations() runs at module load time
237→  // in app-enablebanking.ts (before any route or scheduler code).
238→  startScheduler();
239→}
