 32→// Custom formats
 33→convict.addFormat({
 34→  name: 'tokenExpiration',
 35→  validate(val: unknown) {
 36→    if (val === 'never' || val === 'openid-provider') return;
 37→    if (typeof val === 'number' && Number.isFinite(val) && val >= 0) return;
 38→
 39→    // Handle string values that can be converted to numbers (from env vars)
 40→    if (typeof val === 'string') {
 41→      const numVal = Number(val);
 42→      if (Number.isFinite(numVal) && numVal >= 0) return;
 43→    }
 44→
 45→    throw new Error(
 46→      `Invalid token_expiration value: ${val}: value was "${val}"`,
 47→    );
 48→  },
 49→  coerce(val: unknown): unknown {
 50→    if (val === 'never' || val === 'openid-provider') return val;
 51→    if (typeof val === 'number') return val;
 52→
 53→    // Convert string values to numbers for environment variables
 54→    if (typeof val === 'string') {
 55→      const numVal = Number(val);
 56→      if (Number.isFinite(numVal) && numVal >= 0) return numVal;
 57→    }
 58→
 59→    return val; // Let validate() handle invalid values
 60→  },
 61→});
