  1→// @ts-strict-ignore
  2→// [eb] Scheduled auto-sync: runs every 6 hours when ENABLE_AUTO_SYNC=true.
  3→// Calls Enable Banking service functions directly (no internal HTTP) so no
  4→// auth headers are needed. Per-session grouping ensures consent expiry is
  5→// checked once per bank connection and one user's failure doesn't block others.
  6→import cron from 'node-cron';
  7→
  8→import { getAccountDb } from './account-db.js';
  9→import {
 10→  getBalances,
 11→  getTransactions,
 12→} from './app-enablebanking/enablebanking-service.js';
 13→import {
 14→  RateLimitError,
 15→  SessionExpiredError,
 16→} from './app-enablebanking/errors.js';
 17→import { normalizeTransaction } from './app-enablebanking/utils.js';
 18→
 19→type AccountRow = {
 20→  actual_account_id: string;
 21→  eb_account_uid: string;
 22→  session_id: string;
 23→  valid_until: string | null;
 24→  aspsp_name: string | null;
 25→};
 26→
 27→async function syncOneAccount(account: AccountRow): Promise<void> {
 28→  const db = getAccountDb();
 29→
 30→  // Derive sinceDate from last successful sync (epoch integer -> YYYY-MM-DD).
 31→  const row = db.first(
 32→    'SELECT synced_at FROM eb_sync_log WHERE actual_account_id = ? ORDER BY id DESC LIMIT 1',
 33→    [account.actual_account_id],
 34→  );
 35→  const sinceDate = row?.synced_at
 36→    ? new Date(Number(row.synced_at) * 1000).toISOString().split('T')[0]
 37→    : new Date(Date.now() - 90 * 24 * 3600 * 1000).toISOString().split('T')[0];
 38→
 39→  const { booked, pending } = await getTransactions(
 40→    account.eb_account_uid,
 41→    sinceDate,
 42→  );
 43→  await getBalances(account.eb_account_uid);
 44→
 45→  const allNormalized = [
 46→    ...booked.map(t => normalizeTransaction(t, true)),
 47→    ...pending.map(t => normalizeTransaction(t, false)),
 48→  ];
 49→
 50→  db.mutate(
 51→    `INSERT INTO eb_sync_log (actual_account_id, eb_account_uid, status, transactions_added)
 52→     VALUES (?, ?, 'ok', ?)`,
 53→    [account.actual_account_id, account.eb_account_uid, allNormalized.length],
 54→  );
 55→
 56→  console.log(
 57→    `[scheduler] Synced ${account.actual_account_id}: ${allNormalized.length} transactions`,
 58→  );
 59→}
 60→
 61→async function sleep(ms: number): Promise<void> {
 62→  return new Promise(resolve => setTimeout(resolve, ms));
 63→}
 64→
 65→export type RetryPolicy = {
 66→  maxRetries: number;
 67→  initialDelay: number;
 68→  multiplier: number;
 69→  maxDelay: number;
 70→  jitterFraction: number;
 71→};
 72→
 73→export function applyJitter(delay: number, jitterFraction: number): number {
 74→  // jitter range: [-fraction, +fraction] of the delay
 75→  const jitter = (Math.random() * 2 - 1) * jitterFraction;
 76→  return Math.round(delay * (1 + jitter));
 77→}
 78→
 79→export async function syncAccountWithRetry(
 80→  syncFn: () => Promise<void>,
 81→  sleepFn: (ms: number) => Promise<void>,
 82→  policy: RetryPolicy,
 83→  accountLabel: string,
 84→): Promise<void> {
 85→  let delay = policy.initialDelay;
 86→
 87→  for (let attempt = 0; attempt <= policy.maxRetries; attempt++) {
 88→    try {
 89→      await syncFn();
 90→      return; // success
 91→    } catch (err) {
 92→      // RateLimitError and SessionExpiredError bypass retry - propagate immediately
 93→      if (err instanceof RateLimitError || err instanceof SessionExpiredError) {
 94→        throw err;
 95→      }
 96→      if (attempt === policy.maxRetries) {
 97→        // Final attempt exhausted - propagate to caller for eb_sync_log write
 98→        throw err;
 99→      }
100→      // Cap base delay before applying jitter so jitter may slightly exceed maxDelay
101→      const cappedDelay = Math.min(delay, policy.maxDelay);
102→      const jitteredDelay = applyJitter(cappedDelay, policy.jitterFraction);
103→      console.log(
104→        `[scheduler] Retry ${attempt + 1}/${policy.maxRetries} for ${accountLabel} in ${jitteredDelay}ms`,
105→      );
106→      await sleepFn(jitteredDelay);
107→      delay = Math.min(delay * policy.multiplier, policy.maxDelay);
108→    }
109→  }
110→}
111→
112→const DEFAULT_RETRY_POLICY: RetryPolicy = {
113→  maxRetries: 3,
114→  initialDelay: 5000,
115→  multiplier: 2,
116→  maxDelay: 60000,
117→  jitterFraction: 0.2,
118→};
119→
120→async function runScheduledSync(): Promise<void> {
121→  console.log('[scheduler] Starting scheduled sync run');
122→
123→  const db = getAccountDb();
124→
125→  const rows = db.all(
126→    `SELECT m.actual_account_id, m.eb_account_uid, m.session_id,
127→            s.valid_until, s.aspsp_name
128→     FROM eb_account_map m
129→     JOIN eb_sessions s ON s.id = m.session_id
130→     WHERE m.actual_account_id IS NOT NULL
131→     ORDER BY m.session_id`,
132→    [],
133→  ) as unknown as AccountRow[];
134→
135→  // Group accounts by session so consent expiry is checked once per bank
136→  // connection and one session's failure doesn't block other users.
137→  const sessionGroups = new Map<string, AccountRow[]>();
138→  for (const row of rows) {
139→    const group = sessionGroups.get(row.session_id) ?? [];
140→    group.push(row);
141→    sessionGroups.set(row.session_id, group);
142→  }
143→
144→  let totalSessions = 0;
145→  let totalSynced = 0;
146→  let totalErrors = 0;
147→
148→  for (const [sessionId, accounts] of sessionGroups) {
149→    totalSessions++;
150→    const aspspName = accounts[0]?.aspsp_name ?? 'unknown';
151→    const validUntil = accounts[0]?.valid_until;
152→
153→    // Check consent expiry once per session group.
154→    if (validUntil && new Date(validUntil) < new Date()) {
155→      console.log(
156→        `[scheduler] Skipping session ${sessionId} (${aspspName}): consent expired (${accounts.length} accounts)`,
157→      );
158→      continue;
159→    }
160→
161→    let successCount = 0;
162→
163→    for (const account of accounts) {
164→      try {
165→        await syncAccountWithRetry(
166→          () => syncOneAccount(account),
167→          sleep,
168→          DEFAULT_RETRY_POLICY,
169→          account.actual_account_id,
170→        );
171→        successCount++;
172→        totalSynced++;
173→      } catch (err) {
174→        if (err instanceof RateLimitError) {
175→          // A 429 applies to the entire API connection - don't sleep or retry.
176→          console.log(
177→            `[scheduler] Rate limited on session ${sessionId} (${aspspName}), skipping remaining accounts in session`,
178→          );
179→          break;
180→        }
181→        if (err instanceof SessionExpiredError) {
182→          console.log(
183→            `[scheduler] Session ${sessionId} expired mid-sync, skipping remaining accounts`,
184→          );
185→          break;
186→        }
187→        // All retries exhausted - log error to eb_sync_log
188→        console.error(
189→          `[scheduler] Failed to sync ${account.actual_account_id} after ${DEFAULT_RETRY_POLICY.maxRetries} retries:`,
190→          err,
191→        );
192→        const retryDb = getAccountDb();
193→        retryDb.mutate(
194→          `INSERT INTO eb_sync_log (actual_account_id, eb_account_uid, status, error_message)
195→           VALUES (?, ?, 'error', ?)`,
196→          [
197→            account.actual_account_id,
198→            account.eb_account_uid,
199→            err instanceof Error ? err.message : String(err),
200→          ],
201→        );
202→        totalErrors++;
203→      }
204→    }
205→
206→    console.log(
207→      `[scheduler] Session ${sessionId} (${aspspName}): synced ${successCount}/${accounts.length} accounts`,
208→    );
209→  }
210→
211→  console.log(
212→    `[scheduler] Sync run complete. ${totalSessions} sessions, ${totalSynced} accounts synced, ${totalErrors} errors.`,
213→  );
214→}
