364→/**
365→ * Side-effect hook that routes bank-sync-in-progress status through the Redux
366→ * Notifications system. Dispatches a sticky message while accounts are syncing
367→ * and removes it when sync completes. Call from FinancesApp.
368→ *
369→ * Replaces the BankSyncStatus standalone component.
370→ */
371→export function useBankSyncNotification(): void {
372→  const accountsSyncing = useSelector(
373→    (state: { account: { accountsSyncing: string[] } }) =>
374→      state.account.accountsSyncing,
375→  );
376→  const dispatch = useDispatch();
377→  // Track whether a sync notification is currently active to avoid orphaning
378→  // the notification if the component re-renders between sync start and end.
379→  const wasActive = useRef<boolean>(false);
380→
381→  useEffect(() => {
382→    if (accountsSyncing.length > 0) {
383→      dispatch(
384→        addNotification({
385→          notification: {
386→            id: 'bank-sync-in-progress',
387→            type: 'message',
388→            sticky: true,
389→            message: `Syncing... ${accountsSyncing.length} accounts remaining`,
390→          },
391→        }),
392→      );
393→      wasActive.current = true;
394→    } else if (wasActive.current === true) {
395→      dispatch(removeNotification({ id: 'bank-sync-in-progress' }));
396→      wasActive.current = false;
397→    }
398→  }, [accountsSyncing.length, dispatch]);
399→}
