 14→
 15→export function listenForSyncEvent(store: AppStore, queryClient: QueryClient) {
 16→  // TODO: This is only wired up in App.tsx (desktop). Verify whether
 17→  // mobile also needs these sync-event notifications, and if so wire
 18→  // up listenForSyncEvent in the mobile entry point.
 19→  const unlistenUnauthorized = listen('sync-event', async ({ type }) => {
 20→    if (type === 'unauthorized') {
 21→      store.dispatch(
 22→        addNotification({
 23→          notification: {
 24→            type: 'warning',
 25→            message: 'Unable to authenticate with server',
 26→            sticky: true,
 27→            id: 'auth-issue',
 28→          },
 29→        }),
 30→      );
 31→    }
 32→  });
 33→
 34→  let attemptedSyncRepair = false;
 35→
 36→  const unlistenSuccess = listen('sync-event', event => {
 37→    const prefs = store.getState().prefs.local;
 38→    if (!prefs || !prefs.id) {
 39→      // Do nothing if no budget is loaded
 40→      return;
 41→    }
 42→
 43→    if (event.type === 'success' || event.type === 'applied') {
 44→      if (attemptedSyncRepair) {
 45→        attemptedSyncRepair = false;
 46→
 47→        store.dispatch(
 48→          addNotification({
 49→            notification: {
 50→              title: t('Syncing has been fixed!'),
 51→              message: t('Happy budgeting!'),
 52→              type: 'message',
 53→            },
 54→          }),
 55→        );
 56→      }
 57→
 58→      const tables = event.tables;
 59→
 60→      if (tables.includes('prefs')) {
 61→        store.dispatch(loadPrefs());
 62→      }
 63→
 64→      if (
 65→        tables.includes('categories') ||
 66→        tables.includes('category_groups') ||
 67→        tables.includes('category_mapping')
 68→      ) {
 69→        queryClient.invalidateQueries({
 70→          queryKey: categoryQueries.lists(),
 71→        });
 72→      }
 73→
 74→      if (
 75→        // Sync on accounts change because so that transfer payees are updated
 76→        tables.includes('accounts') ||
 77→        tables.includes('payees') ||
 78→        tables.includes('payee_mapping')
 79→      ) {
 80→        store.dispatch(reloadPayees());
 81→      }
 82→
 83→      if (tables.includes('accounts')) {
 84→        queryClient.invalidateQueries({
 85→          queryKey: accountQueries.lists(),
 86→        });
 87→      }
 88→    } else if (event.type === 'error') {
 89→      const learnMore = `[${t('Learn more')}](https://actualbudget.org/docs/getting-started/sync/#debugging-sync-issues)`;
 90→      const githubIssueLink =
 91→        'https://github.com/actualbudget/actual/issues/new?assignees=&labels=bug&template=bug-report.yml&title=%5BBug%5D%3A+';
 92→
 93→      const ctx = {
 94→        event,
 95→        store,
 96→        learnMore,
 97→        githubIssueLink,
 98→        attemptedSyncRepair,
 99→        setAttemptedSyncRepair: (v: boolean) => {
100→          attemptedSyncRepair = v;
101→        },
102→      };
103→
104→      const handler = syncErrorHandlers[event.subtype] ?? handleUnknownError;
105→      const result = handler(ctx);
106→      if (result.sideEffect) result.sideEffect();
107→      if (result.notification) {
108→        store.dispatch(
109→          addNotification({
110→            notification: { type: 'error', ...result.notification },
111→          }),
112→        );
113→      }
114→    }
115→  });
116→
117→  return () => {
118→    unlistenUnauthorized();
119→    unlistenSuccess();
120→  };
121→}
