 50→export async function bootstrapOpenId(configParameter) {
 51→  if (!('issuer' in configParameter) && !('discoveryURL' in configParameter)) {
 52→    return { error: 'missing-issuer-or-discoveryURL' };
 53→  }
 54→  if (!('client_id' in configParameter)) {
 55→    return { error: 'missing-client-id' };
