 99→ * In v6, discovery() returns a Configuration object that replaces both the
100→ * v5 Issuer and Client instances. For manual issuer configuration (object
101→ * with endpoints), we construct a Configuration directly with ServerMetadata.
102→ */
103→async function setupOpenIdClient(configParameter) {
104→  const redirectUri = new URL(
105→    '/openid/callback',
106→    configParameter.server_hostname,
107→  ).toString();
108→
109→  if (typeof configParameter.issuer === 'string') {
110→    // Auto-discovery: fetch metadata from the issuer URL
111→    // The timeout option (in seconds) applies to discovery and all future requests.
112→    // The [customFetch] option replaces global fetch on the resolved Configuration.
113→    const oidcConfig = await discovery(
114→      new URL(configParameter.issuer),
115→      configParameter.client_id,
116→      configParameter.client_secret,
117→      undefined,
118→      {
119→        timeout: 20,
120→        [customFetch]: createTimeoutFetch(20 * 1000),
121→      },
122→    );
123→    // Attach redirect_uri to the config for use in other functions
124→    oidcConfig[redirectUriSymbol] = redirectUri;
125→    return oidcConfig;
126→  } else {
127→    // Manual configuration: construct ServerMetadata from provided endpoints
128→    const serverMetadata = {
129→      issuer: configParameter.issuer.name,
130→      authorization_endpoint: configParameter.issuer.authorization_endpoint,
131→      token_endpoint: configParameter.issuer.token_endpoint,
132→      userinfo_endpoint: configParameter.issuer.userinfo_endpoint,
133→    };
134→
135→    const oidcConfig = new Configuration(
136→      serverMetadata,
137→      configParameter.client_id,
138→      configParameter.client_secret,
139→    );
140→    oidcConfig[customFetch] = createTimeoutFetch(20 * 1000);
141→    // Attach redirect_uri to the config for use in other functions
142→    oidcConfig[redirectUriSymbol] = redirectUri;
143→    return oidcConfig;
